discrete CurrentDetection
port:
    event input real CurrentSignal;
    event output real ConditionedSignal;
state:
    initial state State1_Standby
        when entry() then
            statehold(5);
        end;
        when receive(CurrentSignal) then
            transition(State2_Working);
        end;
    end;

    state State2_Working
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(State1_Standby);
            out
                send(ConditionedSignal, 1);
        end;
    end;
end;
end;

discrete SignalAmplification
port:
    event input real AmplifiedSignal;
    event output real AmplifiedOutput;
state:
    initial state State1_LowGainMode
        when entry() then
            statehold(5);
        end;
        when receive(AmplifiedSignal) then
            transition(State2_HighGainMode);
        end;
    end;

    state State2_HighGainMode
        when entry() then
            statehold(5);
        end;
        when receive(AmplifiedSignal) then
            transition(State1_LowGainMode);
        end;
        when timeover() then
            transition(State1_LowGainMode);
            out
                send(AmplifiedOutput, 1);
        end;
    end;
end;
end;

discrete SignalProcessing
port:
    event input real ProcessedSignal;
    event output real ProcessedData;
state:
    initial state State1_WaitingForData
        when entry() then
            statehold(5);
        end;
        when receive(ProcessedSignal) then
            transition(State2_ProcessingData);
        end;
    end;

    state State2_ProcessingData
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(State1_WaitingForData);
            out
                send(ProcessedData, 1);
        end;
        when receive(ProcessedSignal) then
            transition(State1_WaitingForData);
        end;
    end;
end;
end;

discrete DataTransmission
port:
    event input real DisplayData;
    event output real DataDisplayed;
state:
    initial state State1_Idle
        when entry() then
            statehold(5);
        end;
        when receive(DisplayData) then
            transition(State2_TransmittingDisplaying);
        end;
    end;

    state State2_TransmittingDisplaying
        when entry() then
            statehold(5);
        end;
        when timeover() then
            transition(State1_Idle);
            out
                send(DataDisplayed, 1);
        end;
    end;
end;
end;

couple CurrentDetectionSystem
import architectureModels.CurrentDetection as CurrentDetection;
import architectureModels.SignalAmplification as SignalAmplification;
