    connect(InstanceCD.ConditionedSignal, InstanceSA.AmplifiedSignal);
    connect(InstanceSA.AmplifiedOutput, InstanceSP.ProcessedSignal);
    connect(InstanceSP.ProcessedData, InstanceDT.DisplayData);
end;
